const PDF_SOURCE_LOOKUP=new Map((window.DBI_PDF_SOURCES?.rows??[]).map(r=>[r.bank+'|'+r.code,r]));
function pdfSourceRecord(e){return PDF_SOURCE_LOOKUP.get(e.bank+'|'+e.code);}
function pdfSourceMatches(e){return pdfSourceRecord(e)?.sources??[];}
function pdfSourceBadge(e){const sources=pdfSourceMatches(e);return sources.length?'<span class="pdf-source-status">Tài liệu tham khảo</span><small class="pdf-source-count">'+sources.length+' nguồn PDF liên quan</small>':'<span class="pdf-source-empty">Chưa tìm được đoạn phù hợp</span>';}

function pdfSourceControls(){return '<select id="pdf-source-filter" aria-label="Nguồn PDF bổ sung">'+opts([['all','Tất cả nguồn PDF'],['related','Có PDF tham khảo'],['missing','Chưa tìm được PDF phù hợp']],S.pdfSource)+'</select>';}

function pdfSourceDetails(e){const r=pdfSourceRecord(e);if(!r?.sources.length)return '';return '<section class="pdf-source-details"><h3>Nguồn PDF tham khảo bổ sung</h3>'+pdfSourceBadge(e)+r.sources.map(c=>'<div class="review-citation pdf-source-citation"><a class="link" href="'+esc(c.url.replace(/#.*$/,'')+'#page='+c.page)+'" target="_blank" rel="noopener noreferrer">'+esc(c.type)+' · '+c.reportYear+' · trang PDF '+c.page+(c.printedPage?' · trang in '+esc(c.printedPage):'')+' ↗</a><small>'+esc(bank(c.bank).label)+'</small><blockquote>'+esc(c.excerpt)+'</blockquote></div>').join('')+'</section>';}
function pdfSourceSearchText(e){return pdfSourceMatches(e).map(s=>[s.type,s.reportYear,s.excerpt,s.terms.join(' ')].join(' ')).join(' ');}
function pooledSourcesCSV(rows){csvDownload([['Ngân hàng','Trụ cột','Nhóm tiêu chí','Mã','Tiêu chí','Mức gộp 2023–2025','Điểm quy đổi (%)','Bằng chứng gốc','URL gốc','Trạng thái bộ điểm','Loại tài liệu bổ sung','URL PDF tham khảo','Năm báo cáo','Trang PDF','Đoạn tham khảo'],...rows.map(e=>[e.bank,D.pillars[e.pillar],e.group,e.code,e.name,e.level,e.percent,e.text,e.urls.join(' | '),'Đã được nhóm duyệt',pdfSourceMatches(e).length?'Tài liệu tham khảo':'Chưa tìm nguồn',pdfSourceMatches(e).map(s=>s.url.replace(/#.*$/,'')+'#page='+s.page).join(' | '),pdfSourceMatches(e).map(s=>s.reportYear).join(' | '),pdfSourceMatches(e).map(s=>s.page).join(' | '),pdfSourceMatches(e).map(s=>s.excerpt).join(' | ')])],'DBI_Bang_chung_2023-2025.csv');}
